// 契约测试：消费者先声明「我期望提供者返回什么」，生成契约
function defineConsumerContract() {
  return {
    consumer: "web-frontend",
    provider: "order-svc",
    interactions: [
      {
        uponReceiving: "获取订单",
        withRequest: { method: "GET", path: "/orders/1" },
        willRespondWith: { status: 200, body: { id: 1, total: 99 } },
      },
    ],
  };
}

const contract = defineConsumerContract();
console.log(contract.consumer, "->", contract.provider);
console.log(contract.interactions[0].withRequest.method,
            contract.interactions[0].withRequest.path);
console.log(JSON.stringify(contract.interactions[0].willRespondWith.body));
